import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String nStr = br.readLine();
        if (nStr == null || nStr.trim().isEmpty()) {
            return;
        }
        int n = Integer.parseInt(nStr.trim());
        if (n == 0) {
            System.out.println();
            return;
        }
        String[] parts = br.readLine().trim().split("\\s+");
        int bucketCount = Math.max(1, n);
        @SuppressWarnings("unchecked")
        ArrayList<Double>[] buckets = new ArrayList[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new ArrayList<>();
        }
        for (int i = 0; i < n && i < parts.length; i++) {
            double val = Double.parseDouble(parts[i]);
            int bucketIndex = (int) (val * bucketCount);
            if (bucketIndex >= bucketCount) {
                bucketIndex = bucketCount - 1;
            }
            buckets[bucketIndex].add(val);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bucketCount; i++) {
            Collections.sort(buckets[i]);
            for (double d : buckets[i]) {
                if (sb.length() > 0) sb.append(' ');
                sb.append(String.format("%.2f", d));
            }
        }
        System.out.println(sb.toString());
    }
}
